WITH filtered_suppliers AS (SELECT * FROM suppliers WHERE city IN ('Singapore', 'Tokyo', 'Berlin')), agg AS (SELECT city, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN country = 'UK' THEN rating ELSE 0 END) AS uk_rating, SUM(CASE WHEN country = 'DE' THEN rating ELSE 0 END) AS de_rating FROM filtered_suppliers GROUP BY city, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END) SELECT * FROM agg WHERE uk_rating > 41 ORDER BY rating_bucket ASC
